import json

def find(folder, name):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.find_assets', json.dumps({'folder_path': folder, 'name': name, 'recursive': True}))['returnValue']

def load(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.load_asset', json.dumps({'asset_path': path}))['returnValue']

def asset_class(path):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.get_asset_class', json.dumps({'asset_path': path}))['returnValue']

def list_properties(instance):
    return execute_tool('editor_toolset.toolsets.object.ObjectTools.list_properties', json.dumps({'instance': instance}))['returnValue']

def inspect(path):
    obj = load(path)
    return {'path': path, 'class': asset_class(path), 'properties': list_properties(obj)}

def run():
    names = ['B_ShooterGame_Elimination', 'LAS_ShooterGame_SharedInput', 'LAS_ShooterGame_StandardHUD', 'W_ShooterHUDLayout', 'HeroData_ShooterGame', 'ID_Rifle', 'WID_Rifle', 'B_WeaponInstance_Rifle', 'AbilitySet_ShooterRifle', 'GA_Weapon_Fire_Rifle_Auto', 'GA_Weapon_Reload_Rifle', 'GE_Damage_RifleAuto', 'B_Rifle', 'ID_Shotgun', 'WID_Shotgun', 'B_WeaponInstance_Shotgun', 'AbilitySet_ShooterShotgun', 'GA_Weapon_Fire_Shotgun', 'GA_Weapon_Reload_Shotgun', 'GE_Damage_Shotgun', 'B_Shotgun']
    found = {}
    for name in names:
        found[name] = find('/ShooterCore', name)
    inspected = {}
    for key in ['B_ShooterGame_Elimination', 'LAS_ShooterGame_SharedInput', 'LAS_ShooterGame_StandardHUD', 'W_ShooterHUDLayout', 'HeroData_ShooterGame', 'ID_Rifle', 'WID_Rifle', 'B_WeaponInstance_Rifle', 'AbilitySet_ShooterRifle', 'ID_Shotgun', 'WID_Shotgun', 'B_WeaponInstance_Shotgun', 'AbilitySet_ShooterShotgun']:
        if found[key]:
            inspected[key] = inspect(found[key][0])
    destinations = find('/ExtractionOps', 'Extraction')
    return {'found': found, 'inspected': inspected, 'destinations': destinations}
